import sys; sys.path.insert(0, str(WORK))
from cvlib import *
R = np.load(WORK/'base_reads.npz'); y=R['y']; res=np.load(WORK/'reserved.npy')
keep = np.setdiff1d(np.arange(768), res)
M = lambda L: R[f'mean_hidden_L{L}'][:,keep]
Y=np.eye(8)[y]
def nz(X):
    Z=(X-X.mean(0))/(X.std(0)+1e-6); return Z/np.linalg.norm(Z,axis=1,keepdims=True)
def kcv(K, lams=(1e-2,), seeds=(0,1,2)):
    out=[]
    for s in seeds:
        f=folds(y,5,s); S=np.zeros((len(y),8))
        for i in range(5):
            tr=f!=i; te=f==i
            A=np.linalg.solve(K[np.ix_(tr,tr)]+lams[0]*np.eye(tr.sum()), Y[tr]-Y[tr].mean(0)); S[te]=K[np.ix_(te,tr)]@A
        out.append((S.argmax(1)==y).mean())
    return round(float(np.mean(out)),4)
q=lambda Cm: Cm+0.5*Cm**2
G={L: nz(M(L))@nz(M(L)).T for L in range(13)}
for j in range(13):
    print(j, 'Mj', kcv(q(G[j])), 'M0+Mj', kcv(q((G[0]+G[j])/2)), 'M1+Mj', kcv(q((G[1]+G[j])/2)))
